import{_ as h,C as r,o as i,c,a2 as a,E as e}from"./chunks/framework.TaNiW7i8.js";const y=JSON.parse('{"title":"Resume a project","description":"","frontmatter":{"title":"Resume a project"},"headers":[],"relativePath":"en/agent/reprendre.md","filePath":"en/agent/reprendre.md"}'),d={name:"en/agent/reprendre.md"};function m(l,t,p,u,g,f){const s=r("AskExample"),o=r("Ask"),n=r("Capture");return i(),c("div",null,[t[0]||(t[0]=a('<h1 id="resume-a-project" tabindex="-1">Resume a project <a class="header-anchor" href="#resume-a-project" aria-label="Permalink to &quot;Resume a project&quot;">​</a></h1><p>This journey picks up where you left off: the agent re-reads what the memory knows about the project, gives you a status, and you propose what comes next. It is the first gesture of a session, see the <a href="/Kessho/en/agent/">cycle</a>.</p><h2 id="what-you-ask-the-agent" tabindex="-1">What you ask the agent <a class="header-anchor" href="#what-you-ask-the-agent" aria-label="Permalink to &quot;What you ask the agent&quot;">​</a></h2>',3)),e(s,{tool:"mem_recall"}),e(s,{tool:"mem_list"}),e(s,{tool:"mem_read_context"}),e(o,{say:"Re-read the session history of kessho-docs.",verb:"mem_read_history",family:"rappel",args:'{"slug":"kessho-docs"}'}),e(o,{say:"Open the archive 2026-10-19-14h32-kessho-docs-refonte-du-socle of kessho-docs.",verb:"mem_read_archive",family:"rappel",args:'{"slug":"kessho-docs","filename":"2026-10-19-14h32-kessho-docs-refonte-du-socle"}'}),e(o,{say:"What do we know about the structure of the kessho-docs repository?",verb:"mem_get_topology",family:"structure",args:'{"project":"kessho-docs"}'}),e(o,{say:"That project was finished but I have to reopen it: put it back among the active projects.",verb:"mem_historize",family:"session",args:'{"slug":"kessho-docs","revive":true}'}),t[1]||(t[1]=a('<p>You do not need to type these sentences word for word: with the procedures Kessho delivers (see <a href="/Kessho/en/agent/connecter.html">Connect the agent</a>), a wish to resume (&quot;let&#39;s pick up&quot;, &quot;where were we?&quot;) or a question about the past (&quot;what did we decide?&quot;) should be enough to trigger the resume, if the agent follows them. If the target project is unclear, the agent asks you to confirm before loading anything.</p><h2 id="what-the-agent-does" tabindex="-1">What the agent does <a class="header-anchor" href="#what-the-agent-does" aria-label="Permalink to &quot;What the agent does&quot;">​</a></h2><p>The tools on this page <strong>read</strong> without writing, except two: <a href="/Kessho/en/reference/mcp/session.html#mem-historize"><code>mem_historize</code></a>, which moves a project, and <a href="/Kessho/en/reference/mcp/git.html#mem-git-sync"><code>mem_git_sync</code></a> (step 5), which fetches, rebases and pushes if the memory is a git repository.</p><ol><li><strong>Find the project.</strong> Most often, it is the slug you give. Without a slug, <a href="/Kessho/en/reference/mcp/rappel.html#mem-recall"><code>mem_recall</code></a> returns the vault inventory so the agent can ask you which one. <a href="/Kessho/en/reference/mcp/structure.html#mem-list"><code>mem_list</code></a> gives the same inventory in detail: projects, domains, phase, last session, scope, number of archives. With <code>include_archived</code> it unfolds archived projects; with <code>archived_only</code> it shows only them. According to the procedure, the agent also tries the name of the folder the session is opened in.</li><li><strong>Load the context.</strong> <a href="/Kessho/en/reference/mcp/rappel.html#mem-recall"><code>mem_recall</code></a> loads the project&#39;s or domain&#39;s context. The procedure has the agent turn it into a briefing: last session and phase, state, decisions, active principles, open goals, key people, next steps. It ends by proposing what comes next (&quot;shall we resume at step X?&quot;).</li><li><strong>Go finer if needed.</strong><ul><li><a href="/Kessho/en/reference/mcp/rappel.html#mem-read-context"><code>mem_read_context</code></a> reads only the <code>context.md</code>, the current snapshot, with no briefing: lighter. <code>slug</code> is required.</li><li><a href="/Kessho/en/reference/mcp/rappel.html#mem-read-history"><code>mem_read_history</code></a> reads the <code>history.md</code>: the chronological thread of sessions, with their count.</li><li><a href="/Kessho/en/reference/mcp/rappel.html#mem-read-archive"><code>mem_read_archive</code></a> reads one given archive (<code>slug</code> and <code>filename</code>, with or without <code>.md</code>), and only inside the project&#39;s <code>archives/</code> folder.</li><li><a href="/Kessho/en/reference/mcp/structure.html#mem-get-topology"><code>mem_get_topology</code></a> reads the project&#39;s topology sheet (its stack, its conventions), possibly that of a branch (<code>branch</code>). A missing sheet is not an error.</li></ul></li><li><strong>Summarize several sessions at once.</strong> That is the job of <a href="/Kessho/en/reference/mcp/rappel.html#mem-digest"><code>mem_digest</code></a>, see <a href="/Kessho/en/agent/chercher.html">Search the memory</a>.</li><li><strong>Catch up.</strong> If the memory is a git repository, the procedure has the agent call <a href="/Kessho/en/reference/mcp/git.html#mem-git-sync"><code>mem_git_sync</code></a> once at the start of the session, to start from what your other machines wrote. Offline or without a remote, it says so in one line and carries on. See <a href="/Kessho/en/agent/synchroniser.html">Sync the memory</a>.</li></ol><h3 id="an-archived-project" tabindex="-1">An archived project <a class="header-anchor" href="#an-archived-project" aria-label="Permalink to &quot;An archived project&quot;">​</a></h3><p>Without an explicit slug, the resume ignores archived projects. With an explicit slug, the agent loads the archived project for <strong>reading</strong> and tells you so. To write to it again, it must first be brought back among the active ones: <a href="/Kessho/en/reference/mcp/session.html#mem-historize"><code>mem_historize</code></a> with <code>revive: true</code> (without <code>revive</code>, it does the opposite and moves a finished project to <code>10-episodes/archived/</code>). While it is archived, <a href="/Kessho/en/reference/mcp/session.html#mem-archive"><code>mem_archive</code></a> refuses to write to it, and <a href="/Kessho/en/reference/mcp/rappel.html#mem-digest"><code>mem_digest</code></a> only summarizes it with <code>from_archived: true</code>.</p><h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2>',7)),e(n,{name:"cles-de-contexte",alt:"The context keys screen: three projects and two domains, to hand to an agent so it finds where you left off; two projects have no summary yet, and the screen says so."}),t[2]||(t[2]=a('<p>The <strong>Context keys</strong> screen (sidebar) lists your projects and domains: each row carries its identifier (the <strong>slug</strong> you give the agent), its summary, its number of archives and the date of its last session. It works as a reminder before you say &quot;let&#39;s pick up…&quot;. The screen is detailed in <a href="/Kessho/en/guide/home.html">Home</a>.</p><p>A row showing &quot;No summary&quot; means nobody has set a summary: the screen counts them, and an agent sets one with <a href="/Kessho/en/reference/mcp/session.html#mem-set-summary"><code>mem_set_summary</code></a> (see <a href="/Kessho/en/agent/archiver.html">Archive a session</a>).</p><p>The resume itself changes nothing on screen, since it only reads. Only <code>mem_historize</code> (which moves the project) and <code>mem_git_sync</code> (which can bring in notes written on another machine) change the memory; the freshness indicator shows it like any agent write (see <a href="/Kessho/en/guide/zones.html">Zones</a>).</p>',3))])}const w=h(d,[["render",m]]);export{y as __pageData,w as default};
